import '../styles/cart.css';

function Cart() {
    const item1 = 15;
    const item2 = 20;
    return (
        <div className="cart">
            <h1>Cart</h1>
            <p>Item 1: {item1}€</p>
            <p>Item 2: {item2}€</p>
            <div className="total">
                <p>Total: {item1 + item2}€</p>
            </div>
        </div>
    );
}
export default Cart;
